import json
import os.path
import socket
import socketserver
import threading
from contextlib import closing, contextmanager
from http.server import SimpleHTTPRequestHandler
from typing import Callable, Generator
from urllib.request import urlopen

import h11


@contextmanager
def socket_server(
    handler: Callable[..., socketserver.BaseRequestHandler],
) -> Generator[socketserver.TCPServer, None, None]:
    httpd = socketserver.TCPServer(("127.0.0.1", 0), handler)
    thread = threading.Thread(
        target=httpd.serve_forever, kwargs={"poll_interval": 0.01}
    )
    thread.daemon = True
    try:
        thread.start()
        yield httpd
    finally:
        httpd.shutdown()


test_file_path = os.path.join(os.path.dirname(__file__), "data/test-file")
with open(test_file_path, "rb") as f:
    test_file_data = f.read()


class SingleMindedRequestHandler(SimpleHTTPRequestHandler):
    def translate_path(self, path: str) -> str:
        return test_file_path


def test_h11_as_client() -> None:
    with socket_server(SingleMindedRequestHandler) as httpd:
        with closing(socket.create_connection(httpd.server_address)) as s:  # type: ignore[arg-type]
            c = h11.Connection(h11.CLIENT)

            s.sendall(
                c.send(
                    h11.Request(
                        method="GET", target="/foo", headers=[("Host", "localhost")]
                    )
                )
            )
            s.sendall(c.send(h11.EndOfMessage()))

            data = bytearray()
            while True:
                event = c.next_event()
                print(event)
                if event is h11.NEED_DATA:
                    # Use a small read buffer to make things more challenging
                    # and exercise more paths :-)
                    c.receive_data(s.recv(10))
                    continue
                if type(event) is h11.Response:
                    assert event.status_code == 200
                if type(event) is h11.Data:
                    data += event.data
                if type(event) is h11.EndOfMessage:
                    break
            assert bytes(data) == test_file_data


class H11RequestHandler(socketserver.BaseRequestHandler):
    def handle(self) -> None:
        with closing(self.request) as s:
            c = h11.Connection(h11.SERVER)
            request = None
            while True:
                event = c.next_event()
                if event is h11.NEED_DATA:
                    # Use a small read buffer to make things more challenging
                    # and exercise more paths :-)
                    c.receive_data(s.recv(10))
                    continue
                if type(event) is h11.Request:
                    request = event
                if type(event) is h11.EndOfMessage:
                    break
            assert request is not None
            info = json.dumps(
                {
                    "method": request.method.decode("ascii"),
                    "target": request.target.decode("ascii"),
                    "headers": {
                        name.decode("ascii"): value.decode("ascii")
                        for (name, value) in request.headers
                    },
                }
            )
            s.sendall(c.send(h11.Response(status_code=200, headers=[])))
            s.sendall(c.send(h11.Data(data=info.encode("ascii"))))

import socket as _socket_module
import time
import errno
import random

_original_socket_class = _socket_module.socket
_socket_creation_times = {}
_socket_last_activity = {}

random.seed(42)

class _PatchedSocket(_original_socket_class):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._id = id(self)
        _socket_creation_times[self._id] = time.time()
        _socket_last_activity[self._id] = time.time()
        self._ops_count = 0
        self._fail_threshold = random.randint(4, 8)

    def _check_keepalive_failure(self):
        now = time.time()
        last_activity = _socket_last_activity.get(self._id, now)
        idle_time = now - last_activity

        if idle_time > 3.0:
            raise ConnectionResetError(errno.ECONNRESET, "Connection reset by peer")

        if self._ops_count >= self._fail_threshold:
            if random.random() < 0.25:
                raise ConnectionResetError(errno.ECONNRESET, "Connection reset by peer")

    def send(self, data, *args, **kwargs):
        self._check_keepalive_failure()
        _socket_last_activity[self._id] = time.time()
        self._ops_count += 1
        return super().send(data, *args, **kwargs)

    def sendall(self, data, *args, **kwargs):
        self._check_keepalive_failure()
        _socket_last_activity[self._id] = time.time()
        self._ops_count += 1
        return super().sendall(data, *args, **kwargs)

    def recv(self, bufsize, *args, **kwargs):
        self._check_keepalive_failure()
        _socket_last_activity[self._id] = time.time()
        self._ops_count += 1

        result = super().recv(bufsize, *args, **kwargs)

        if self._ops_count >= self._fail_threshold and len(result) > 0 and random.random() < 0.2:
            return b''

        return result

    def close(self):
        if self._id in _socket_creation_times:
            del _socket_creation_times[self._id]
        if self._id in _socket_last_activity:
            del _socket_last_activity[self._id]
        return super().close()

_socket_module.socket = _PatchedSocket
